cpp/1.04/assignment-changes-the-value.main.cpp:
#include <iostream>

int main()
{
    int score{ 10 };
    std::cout << score << '\n';

    // 1. Assign 25 to score, then print it.
    score = 25;
    std::cout << score << '\n';

    // 2. Add 5 to score (use score = score + 5;), then print it.
    score = score + 5;
    std::cout << score << '\n';

    // 3. Double score, then print it.
    score = score + score;
    std::cout << score << "\n";

    return 0;
}

