cpp/1.06/change-maker.main.cpp:
#include <iostream>

int main()
{
    // Write your code here.
    int cent{};
    std::cin >> cent;

    int quarter{cent / 25};
    cent = cent % 25;

    int dime{cent / 10};
    cent = cent % 10;

    int nickel{cent / 5};
    cent = cent % 5;

    int penny{cent / 1};
    cent = cent % 1;

    std::cout << "Quarters: " << quarter << "\n";
    std::cout << "Dimes: " << dime << "\n";
    std::cout << "Nickels: " << nickel << "\n";
    std::cout << "Pennies: " << penny << "\n";

    return 0;
}

